// Helpers for tests that read test-vectors/*.json (generated by tools/refgen).
#pragma once

#include <catch2/catch_test_macros.hpp>

#include <fstream>
#include <nlohmann/json.hpp>
#include <stdexcept>
#include <string>

#include "yap/common/bytes.hpp"
#include "yap/common/hex.hpp"

namespace yap::test {

using json = nlohmann::json;

inline json load_vectors(const std::string& name) {
    std::ifstream in(std::string(YAP_TEST_VECTORS_DIR) + "/" + name);
    if (!in) {
        throw std::runtime_error("cannot open test vector file " + name);
    }
    json doc = json::parse(in);
    REQUIRE(doc.at("version") == 1);
    return doc.at("vectors");
}

inline Bytes jhex(const json& j) {
    auto b = from_hex(j.get<std::string>());
    if (!b) {
        throw std::runtime_error("bad hex in vectors");
    }
    return *b;
}

template <std::size_t N>
FixedBytes<N> jhexn(const json& j) {
    auto b = from_hex_fixed<N>(j.get<std::string>());
    if (!b) {
        throw std::runtime_error("bad fixed hex in vectors");
    }
    return *b;
}

inline std::uint64_t ju64(const json& j) { return std::stoull(j.get<std::string>()); }

inline std::string as_string(ByteView b) { return {reinterpret_cast<const char*>(b.data()), b.size()}; }

}  // namespace yap::test
